"", "  # Knit a copy in the output directory: rendering in place would write", 
"  # intermediates into the app directory.", "  template <- report_template()", 
"  rmd <- file.path(out_dir, paste0(basename_out, \".Rmd\"))", 
"  file.copy(template, rmd, overwrite = TRUE)", "", "  say(0.1, \"Checking the export against the spec\")", 
