"      ),", "      output_file = basename(html),", "      output_dir = out_dir,", 
"      intermediates_dir = out_dir,", "      knit_root_dir = out_dir,", 
"      params = list(", "        data_file      = data_file,", 
"        spec_file      = spec_file,", "        r_dir          = r_dir,", 
