# ==== R/spec.R (155 lines) ====
.embedded[["R/spec.R"]] <-
c("# ---------------------------------------------------------------------------", 
"# Reading and interrogating a study spec.", "#", "# Nothing in this file knows anything about VITAL-HMB. Everything study-specific", 
"# lives in spec/*.yaml.", "# ---------------------------------------------------------------------------", 
"", "#' Read a study spec from YAML.", "#'", "#' Applies defaults and checks the spec is internally coherent. Problems with", 
"#' the spec itself are the study team's problem, not the data's, so they abort", 
"#' immediately with a message naming the offending variable.", 
"#'", "#' @param path Path to a spec YAML file.", "#' @return A list with class `cohort_spec`.", 
"read_spec <- function(path) {", "  if (!file.exists(path)) {", 
"    stop(sprintf(\"Spec file not found: %s\", path), call. = FALSE)", 
"  }", "  spec <- yaml::yaml.load_file(path)", "", "  spec$options <- utils::modifyList(", 
"    list(missingness_threshold = 0.60, min_complete_cases = 30L),", 
"    spec$options %||% list()", "  )", "  spec$na_strings <- spec$na_strings %||% c(\"\", \"Unknown\", \"N/A\", \"NA\")", 
"  spec$checks     <- spec$checks %||% list()", "  spec$variables  <- spec$variables %||% list()", 
"", "  for (f in c(\"outcome\", \"filter\", \"record_id_column\")) {", 
"    if (is.null(spec[[f]])) {", "      stop(sprintf(\"Spec is missing the required `%s` section.\", f), call. = FALSE)", 
"    }", "  }", "", "  # Normalise each variable, filling in defaults that the YAML may omit.", 
"  spec$variables <- lapply(spec$variables, function(v) {", "    if (is.null(v$name)) {", 
"      stop(\"Every entry under `variables` needs a `name`.\", call. = FALSE)", 
"    }", "    v$type     <- v$type %||% \"numeric\"", "    v$label    <- v$label %||% v$name", 
"    v$domain   <- v$domain %||% \"Other\"", "    v$required <- isTRUE(v$required)", 
"", "    if (!v$type %in% c(\"numeric\", \"factor\", \"binary\", \"ordinal\", \"derived\")) {", 
"      stop(sprintf(\"Variable `%s` has unknown type `%s`.\", v$name, v$type),", 
"           call. = FALSE)", "    }", "    if (v$type == \"derived\") {", 
"      if (is.null(v$expr) && is.null(v$fn)) {", "        stop(sprintf(\"Derived variable `%s` needs either `expr` or `fn`.\", v$name),", 
"             call. = FALSE)", "      }", "    } else if (is.null(v$source)) {", 
"      stop(sprintf(\"Variable `%s` is type `%s` and needs a `source` column.\",", 
"                   v$name, v$type), call. = FALSE)", "    }", 
"    if (v$type == \"binary\") v$levels <- v$levels %||% c(\"No\", \"Yes\")", 
"", "    # YAML 1.1 reads bare No/Yes/On/Off as booleans, which turns a declared", 
"    # level list into TRUE/FALSE and makes every real value look undeclared.", 
"    # It is a silent, total data loss, so name it precisely.", 
"    if (!is.null(v$levels)) {", "      lv <- unlist(v$levels)", 
"      if (is.logical(lv)) {", "        stop(sprintf('Variable `%s`: `levels` was read as true/false. YAML treats bare No and Yes as booleans -- quote them, e.g. levels: [\"No\", \"Yes\"].',", 
"                     v$name), call. = FALSE)", "      }", "      v$levels <- as.character(lv)", 
"    }", "    if (!is.null(v$recode)) {", "      if (any(vapply(v$recode, is.logical, logical(1)))) {", 
"        stop(sprintf('Variable `%s`: a `recode` value was read as true/false. Quote bare No and Yes in YAML.',", 
"                     v$name), call. = FALSE)", "      }", "    }", 
"    if (v$type == \"ordinal\" && is.null(v$scores)) {", "      stop(sprintf(\"Ordinal variable `%s` needs a `scores` map.\", v$name),", 
"           call. = FALSE)", "    }", "    v", "  })", "", "  nms <- vapply(spec$variables, `[[`, character(1), \"name\")", 
"  if (anyDuplicated(nms)) {", "    stop(sprintf(\"Duplicate variable names in spec: %s\",", 
"                 paste(unique(nms[duplicated(nms)]), collapse = \", \")),", 
"         call. = FALSE)", "  }", "  if (spec$outcome$name %in% nms) {", 
"    stop(sprintf(\"`%s` is both the outcome and a variable; give one a new name.\",", 
"                 spec$outcome$name), call. = FALSE)", "  }", 
"", "  spec$domains <- spec$domains %||% unique(", "    vapply(spec$variables, `[[`, character(1), \"domain\"))", 
"", "  structure(spec, class = c(\"cohort_spec\", \"list\"))", 
"}", "", "#' Variables in a spec, optionally filtered.", "#'", 
"#' @param spec A `cohort_spec`.", "#' @param type Optional character vector of types to keep.", 
"#' @param domain Optional domain to keep.", "spec_variables <- function(spec, type = NULL, domain = NULL) {", 
"  v <- spec$variables", "  if (!is.null(type)) {", "    v <- Filter(function(x) x$type %in% type, v)", 
"  }", "  if (!is.null(domain)) {", "    v <- Filter(function(x) identical(x$domain, domain), v)", 
"  }", "  v", "}", "", "#' Look up a single variable definition by name.", 
"spec_variable <- function(spec, name) {", "  for (v in spec$variables) if (identical(v$name, name)) return(v)", 
"  NULL", "}", "", "#' Resolve a spec `source` string against real export column names.", 
"#'", "#' Exact match wins outright. Failing that, a substring match is accepted only", 
"#' if it is unique — a substring hitting several columns is an error, never a", 
"#' first-match-wins guess, because that is precisely how the original report", 
"#' silently attached itself to the wrong column.", "#'", "#' @param source The `source` string from the spec.", 
"#' @param columns Character vector of column names in the export.", 
"#' @return A list with `status` (\"ok\", \"missing\" or \"ambiguous\"), the matched", 
"#'   `column` when status is \"ok\", and `candidates` when ambiguous.", 
"match_column <- function(source, columns) {", "  if (source %in% columns) {", 
"    return(list(status = \"ok\", column = source, candidates = source))", 
"  }", "  hits <- columns[startsWith(columns, source)]", "  if (length(hits) != 1L) {", 
"    contains <- columns[vapply(columns, function(x)", "      grepl(source, x, fixed = TRUE), logical(1))]", 
"    # Prefer a unique prefix match; fall back to a unique substring match.", 
"    hits <- if (length(hits) > 1L) hits else contains", "  }", 
"  if (length(hits) == 1L) {", "    list(status = \"ok\", column = hits, candidates = hits)", 
"  } else if (length(hits) == 0L) {", "    list(status = \"missing\", column = NA_character_, candidates = character(0))", 
"  } else {", "    list(status = \"ambiguous\", column = NA_character_, candidates = hits)", 
"  }", "}", "", "`%||%` <- function(x, y) if (is.null(x)) y else x"
)

# ==== R/tables.R (454 lines) ====
.embedded[["R/tables.R"]] <-
c("# ---------------------------------------------------------------------------", 
"# Table builders. Everything returns a flextable, because the output formats", 
"# are DOCX and PDF. gt is HTML-first and must not appear here.", 
"#", "# The statistical conventions are the original report's and are deliberate:", 
"#   continuous   median [IQR] and mean (SD), Wilcoxon rank-sum", 
"#   categorical  n (%) to one decimal, chi-square, Fisher when a cell is thin", 
"#   univariate   logistic regression, odds ratio with a Wald 95% CI", 
"# ---------------------------------------------------------------------------", 
"", "# --- small formatting helpers ----------------------------------------------", 
"", "fmt_p <- function(p) {", "  ifelse(is.na(p), \"-\",", "         ifelse(p < 0.001, \"<0.001\", formatC(p, format = \"f\", digits = 3)))", 
"}", "", "fmt_est <- function(x) formatC(x, format = \"f\", digits = 2)", 
"", "# Which outcome level counts as the event.", "outcome_levels <- function(spec) {", 
"  lv <- unname(unlist(spec$outcome$labels))", "  if (is.null(lv) || length(lv) < 2) lv <- c(\"0\", \"1\")", 
"  lv", "}", "", "# Short name for the event, for table titles: \"Demographics by HMB status\"", 
"# reads better than the full outcome label or the bare variable name.", 
"outcome_positive_label <- function(spec) {", "  lv <- outcome_levels(spec)", 
"  lv[[length(lv)]]", "}", "", "#' Standard theme so every table in the report looks the same in Word.", 
"style_table <- function(ft, title = NULL, subtitle = NULL) {", 
"  ft <- flextable::theme_booktabs(ft)", "  # Pin the face explicitly: without it the HTML render falls back to the", 
"  # browser's serif default, so tables came out in Times inside a sans page.", 
"  ft <- flextable::font(ft, fontname = \"Arial\", part = \"all\")", 
"  ft <- flextable::fontsize(ft, size = 9, part = \"all\")", 
"  ft <- flextable::bold(ft, part = \"header\")", "  ft <- flextable::padding(ft, padding.top = 2, padding.bottom = 2, part = \"all\")", 
"  if (!is.null(title)) {", "    ft <- flextable::add_header_lines(ft, values = title)", 
"    ft <- flextable::bold(ft, i = 1, part = \"header\")", "  }", 
"  if (!is.null(subtitle)) {", "    ft <- flextable::add_footer_lines(ft, values = subtitle)", 
"    ft <- flextable::fontsize(ft, size = 8, part = \"footer\")", 
"    ft <- flextable::italic(ft, part = \"footer\")", "  }", 
"  ft <- flextable::align(ft, j = 1, align = \"left\", part = \"all\")", 
"  ft <- flextable::autofit(ft)", "", "  # autofit() sizes columns to their content with no page cap, and the wider", 
"  # summary tables come out at up to twice the printable width -- Word then", 
"  # clips both edges. Scale the columns down proportionally so every table", 
"  # fits the 6.5 in text column of a letter page with 1 in margins, keeping", 
"  # autofit's relative proportions. Scale the widths autofit actually set", 
"  # (dim), not the dim_pretty estimate: autofit pads each column, so the two", 
"  # disagree by enough to leave the widest tables still overflowing.", 
"  # Target a hair under the 6.5 in text column so per-column twip rounding", 
"  # cannot nudge the grid back over the page edge.", "  page_w <- 6.49", 
"  min_w  <- 0.7   # narrower columns wrap \"<0.001\" and \"p-value\" mid-token", 
"  widths <- dim(ft)$widths", "  if (sum(widths) > page_w) {", 
"    widths <- widths * (page_w / sum(widths))", "    if (min_w * length(widths) < page_w && any(widths < min_w)) {", 
"      deficit <- sum(pmax(0, min_w - widths))", "      slack   <- pmax(0, widths - min_w)", 
"      widths  <- pmax(widths, min_w) - deficit * slack / sum(slack)", 
"    }", "    ft <- flextable::width(ft, width = widths)", "  }", 
"  ft", "}", "", "# --- significance testing ---------------------------------------------------", 
"", "#' Chi-square with a Fisher fallback, or Wilcoxon for continuous variables.", 
"#'", "#' Supplied to gtsummary as a custom test so the report's p-values follow the", 
"#' original conventions rather than gtsummary's defaults.", 
"cohort_test <- function(data, variable, by, ...) {", "  x <- data[[variable]]", 
"  g <- data[[by]]", "  keep <- !is.na(x) & !is.na(g)", "  x <- x[keep]", 
"  g <- droplevels(as.factor(g[keep]))", "", "  none <- dplyr::tibble(p.value = NA_real_, method = \"not tested\")", 
"  if (nlevels(g) < 2L || length(x) < 3L) return(none)", "", 
"  if (is.numeric(x)) {", "    if (stats::sd(x, na.rm = TRUE) == 0) return(none)", 
