"  nms <- vapply(v, `[[`, character(1), \"name\")", "  nms[nms %in% names(data)]", 
"}", "", "#' Attach spec labels so gtsummary prints human wording, not variable names.", 
"label_columns <- function(data, spec) {", "  for (nm in names(data)) {", 
"    v <- spec_variable(spec, nm)", "    lab <- if (!is.null(v)) v$label else if (identical(nm, spec$outcome$name))", 
