"}", "", "#' Univariate associations across a set of domains.", 
"univariate_results <- function(data, spec, domains) {", "  vars <- unlist(lapply(domains, function(dm) domain_vars(data, spec, dm)))", 
"  if (!length(vars)) return(NULL)", "  out <- lapply(vars, function(nm) univariate_fit(data, spec, nm))", 
