"univariate_flextable <- function(res, title = NULL) {", "  if (is.null(res) || !nrow(res)) return(NULL)", 
"  disp <- data.frame(", "    Predictor = res$term,", "    OR = ifelse(is.na(res$or), \"-\", fmt_est(res$or)),", 
"    `95% CI` = ifelse(is.na(res$or), \"-\",", "                      sprintf(\"%s - %s\", fmt_est(res$lcl), fmt_est(res$ucl))),", 
"    p = ifelse(is.na(res$p), \"-\", fmt_p(res$p)),", "    Note = res$note,", 
"    check.names = FALSE, stringsAsFactors = FALSE)", "", "  ft <- flextable::flextable(disp)", 
"  ft <- flextable::italic(ft, i = which(nzchar(res$note)), j = 5)", 
"  style_table(ft, title = title,", "              subtitle = \"Unadjusted logistic regression. OR with Wald 95% CI.\")", 
"}", "", "# --- data quality tables ----------------------------------------------------", 
"", "missingness_flextable <- function(quality, spec, top = NULL) {", 
"  m <- quality$missingness", "  if (is.null(m) || !nrow(m)) return(NULL)", 
"  if (!is.null(top)) m <- utils::head(m, top)", "  disp <- data.frame(", 
"    Variable = m$label, Domain = m$domain,", "    `N missing` = m$n_missing, `% missing` = m$pct_missing,", 
"    check.names = FALSE, stringsAsFactors = FALSE)", "  style_table(flextable::flextable(disp), title = \"Missingness by variable\")", 
"}", "", "checks_flextable <- function(quality) {", "  ck <- quality$checks", 
"  if (is.null(ck) || !nrow(ck)) return(NULL)", "  disp <- data.frame(", 
"    Check = ck$check, Evaluable = ck$evaluable,", "    Violations = ck$violations, `% violating` = ck$pct,", 
"    check.names = FALSE, stringsAsFactors = FALSE)", "  style_table(flextable::flextable(disp), title = \"Variable consistency checks\",", 
"              subtitle = \"Records where the rule cannot be evaluated are excluded from the denominator.\")", 
"}", "", "range_flextable <- function(quality) {", "  r <- quality$out_of_range", 
"  if (is.null(r) || !nrow(r)) return(NULL)", "  disp <- data.frame(", 
"    Variable = r$label,", "    `Valid range` = sprintf(\"%s to %s\", r$low, r$high),", 
"    `Values dropped` = r$n,", "    check.names = FALSE, stringsAsFactors = FALSE)", 
"  style_table(flextable::flextable(disp),", "              title = \"Values outside the plausible range\",", 
"              subtitle = \"These were set to missing before analysis.\")", 
"}", "", "levels_flextable <- function(quality) {", "  b <- quality$bad_levels", 
"  if (is.null(b) || !nrow(b)) return(NULL)", "  disp <- data.frame(", 
"    Variable = b$label, Issue = b$issue, Values = b$value, N = b$n,", 
"    check.names = FALSE, stringsAsFactors = FALSE)", "  style_table(flextable::flextable(disp),", 
"              title = \"Responses not declared in the spec\",", 
"              subtitle = \"These were left as missing rather than folded into an existing category.\")", 
"}", "", "# --- missingness mechanism --------------------------------------------------", 
"", "#' Columns that are exact linear combinations of earlier ones.", 
"#'", "#' Little's test inverts a covariance matrix, so a derived variable such as", 
"#' mean arterial pressure -- exactly (sbp + 2*dbp)/3 -- makes it singular and", 
"#' the test fails outright. Rank detection drops the redundant columns instead.", 
"independent_columns <- function(data, vars) {", "  m <- as.matrix(data[, vars, drop = FALSE])", 
"  # Impute to the mean only to detect dependence; an exact linear relationship", 
"  # survives mean imputation, and the imputed copy is not used for anything else.", 
"  for (j in seq_len(ncol(m))) {", "    mu <- mean(m[, j], na.rm = TRUE)", 
"    m[is.na(m[, j]), j] <- mu", "  }", "  m <- scale(m)", "  m[is.na(m)] <- 0", 
"  q <- qr(m)", "  vars[sort(q$pivot[seq_len(q$rank)])]", "}", 
"", "#' Little's MCAR test over numeric variables below the missingness threshold.", 
"mcar_result <- function(data, spec) {", "  thresh <- spec$options$missingness_threshold %||% 0.60", 
"  num <- names(data)[vapply(data, is.numeric, logical(1))]", 
"  num <- num[vapply(num, function(nm) mean(is.na(data[[nm]])) < thresh, logical(1))]", 
"  num <- num[vapply(num, function(nm) stats::sd(data[[nm]], na.rm = TRUE) > 0, logical(1))]", 
"  if (length(num) < 2L) {", "    return(list(ok = FALSE, message = \"Not enough numeric variables to test.\"))", 
"  }", "", "  keep <- independent_columns(data, num)", "  dropped <- setdiff(num, keep)", 
"  if (length(keep) < 2L) {", "    return(list(ok = FALSE,", 
"                message = \"Not enough independent numeric variables to test.\"))", 
"  }", "", "  res <- tryCatch(naniar::mcar_test(data[, keep, drop = FALSE]),", 
"                  error = function(e) NULL)", "  if (is.null(res)) {", 
"    return(list(ok = FALSE,", "                message = \"Little's test could not be computed on these variables.\"))", 
"  }", "  list(ok = TRUE, n_vars = length(keep), dropped = dropped,", 
"       statistic = res$statistic, df = res$df, p.value = res$p.value,", 
"       missing.patterns = res$missing.patterns)", "}", "", "#' Chi-square probe of each variable's missingness against the outcome.", 
"#'", "#' A small p-value says the data are not missing completely at random.", 
"missing_vs_outcome <- function(data, spec) {", "  y <- data[[spec$outcome$name]]", 
"  vars <- setdiff(names(data), c(\".record_id\", spec$outcome$name))", 
"  rows <- lapply(vars, function(nm) {", "    miss <- is.na(data[[nm]])", 
"    if (!any(miss) || all(miss)) return(NULL)", "    tab <- table(miss, y)", 
"    if (nrow(tab) < 2L || ncol(tab) < 2L) return(NULL)", "    p <- tryCatch({", 
"      ex <- suppressWarnings(stats::chisq.test(tab)$expected)", 
"      if (any(ex < 5)) stats::fisher.test(tab)$p.value", "      else stats::chisq.test(tab, correct = FALSE)$p.value", 
"    }, error = function(e) NA_real_)", "    v <- spec_variable(spec, nm)", 
"    data.frame(variable = nm, label = if (!is.null(v)) v$label else nm,", 
"               pct_missing = round(100 * mean(miss), 1), p = p,", 
"               stringsAsFactors = FALSE)", "  })", "  rows <- Filter(Negate(is.null), rows)", 
"  if (!length(rows)) return(NULL)", "  out <- do.call(rbind, rows)", 
"  out[order(out$p), , drop = FALSE]", "}", "", "missing_vs_outcome_flextable <- function(mv) {", 
"  if (is.null(mv) || !nrow(mv)) return(NULL)", "  disp <- data.frame(", 
"    Variable = mv$label, `% missing` = mv$pct_missing, p = fmt_p(mv$p),", 
"    check.names = FALSE, stringsAsFactors = FALSE)", "  style_table(flextable::flextable(disp),", 
"              title = \"Does missingness depend on the outcome?\",", 
"              subtitle = \"A small p-value suggests missingness is related to the outcome (not MCAR).\")", 
"}", "", "# --- plots ------------------------------------------------------------------", 
"", "#' Boxplots of the most strongly associated numeric variables by outcome.", 
"outcome_plots <- function(data, spec, res, max_panels = 6L) {", 
"  if (is.null(res)) return(NULL)", "  num <- vapply(res$variable, function(nm) is.numeric(data[[nm]]), logical(1))", 
"  cand <- res[num & !is.na(res$p), , drop = FALSE]", "  if (!nrow(cand)) return(NULL)", 
"  cand <- cand[order(cand$p), , drop = FALSE]", "  vars <- utils::head(unique(cand$variable), max_panels)", 
"", "  y <- spec$outcome$name", "  long <- do.call(rbind, lapply(vars, function(nm) {", 
"    v <- spec_variable(spec, nm)", "    data.frame(panel = if (!is.null(v)) v$label else nm,", 
"               value = data[[nm]], group = data[[y]],", "               stringsAsFactors = FALSE)", 
"  }))", "  long <- long[!is.na(long$value) & !is.na(long$group), , drop = FALSE]", 
"  if (!nrow(long)) return(NULL)", "", "  ggplot2::ggplot(long, ggplot2::aes(x = group, y = value, fill = group)) +", 
"    ggplot2::geom_boxplot(outlier.size = 0.6, alpha = 0.85) +", 
"    ggplot2::facet_wrap(~panel, scales = \"free_y\") +", "    ggplot2::labs(x = NULL, y = NULL) +", 
"    ggplot2::theme_minimal(base_size = 9) +", "    ggplot2::theme(legend.position = \"none\",", 
"                   strip.text = ggplot2::element_text(face = \"bold\", size = 8))", 
"}")

# ==== R/validate.R (280 lines) ====
.embedded[["R/validate.R"]] <-
c("# ---------------------------------------------------------------------------", 
"# The schema gate.", "#", "# This file exists because the original report matched columns by substring of", 
"# the REDCap label and returned an all-NA column when nothing matched. A whole", 
"# analysis then ran on nothing. Every check below turns one variant of that", 
"# silent failure into a loud one.", "#", "# Two severities:", 
"#   hard  the render cannot proceed; report every problem at once, never stop", 
"#         at the first one, because staff re-export once and want the full list", 
"#   soft  the render proceeds and the problem is surfaced in data quality", 
"# ---------------------------------------------------------------------------", 
"", "#' Read a REDCap label export.", "#'", "#' REDCap label exports are ISO-8859-1. Reading one as UTF-8 does not error; it", 
"#' silently mangles any non-ASCII header, after which every column lookup", 
"#' misses and the analytic sample comes back empty.", "#'", 
"#' @param path Path to the CSV.", "#' @return A data.frame, all columns character, names unmodified.", 
"read_export <- function(path, encoding = \"ISO-8859-1\") {", 
"  if (!file.exists(path)) {", "    stop(sprintf(\"Data file not found: %s\", path), call. = FALSE)", 
"  }", "  out <- readr::read_csv(", "    path,", "    col_types = readr::cols(.default = readr::col_character()),", 
"    locale    = readr::locale(encoding = encoding),", "    na        = character(),          # keep blanks; na_strings handles them", 
"    progress  = FALSE,", "    name_repair = \"minimal\"", "  )", 
"  as.data.frame(out, check.names = FALSE, stringsAsFactors = FALSE)", 
"}", "", "fail <- function(code, message, detail = NULL) {", 
"  list(code = code, message = message, detail = detail)", "}", 
"", "# Does this export look like it came out of REDCap with raw values rather than", 
"# labels? Raw exports use lowercase snake_case field names with no spaces.", 
"looks_like_raw_export <- function(columns) {", "  if (!length(columns)) return(FALSE)", 
"  snakey <- grepl(\"^[a-z][a-z0-9_]*$\", columns)", "  mean(snakey) > 0.8", 
"}", "", "#' Validate an export against a spec.", "#'", "#' @param raw A data.frame as returned by [read_export()].", 
"#' @param spec A `cohort_spec` from [read_spec()].", "#' @return An object of class `cohort_validation`.", 
"validate_export <- function(raw, spec) {", "  hard <- list()", 
"  soft <- list()", "  cols <- names(raw)", "", "  # --- structural columns --------------------------------------------------", 
"", "  structural <- list(", "    record_id = spec$record_id_column,", 
"    event     = spec$filter$event_column,", "    outcome   = spec$outcome$source", 
"  )", "  resolved_structural <- list()", "", "  for (key in names(structural)) {", 
"    src <- structural[[key]]", "    m <- match_column(src, cols)", 
"    resolved_structural[[key]] <- m$column", "    if (m$status == \"missing\") {", 
"      msg <- sprintf('Column \"%s\" not found in the upload.', src)", 
"      if (key == \"outcome\" && looks_like_raw_export(cols)) {", 
"        msg <- paste(msg, \"This looks like a raw-value export -- re-export from\",", 
"                     \"REDCap with labels.\")", "      } else {", 
"        msg <- paste(msg, \"Check that this is the right file and that the\",", 
"                     \"column has not been renamed.\")", "      }", 
"      hard <- c(hard, list(fail(paste0(\"missing_\", key), msg)))", 
"    } else if (m$status == \"ambiguous\") {", "      hard <- c(hard, list(fail(", 
"        paste0(\"ambiguous_\", key),", "        sprintf('Column \"%s\" matches %d columns, so we cannot tell which one is meant: %s',", 
"                src, length(m$candidates), paste(sprintf('\"%s\"', m$candidates), collapse = \", \")),", 
"        m$candidates)))", "    }", "  }", "", "  # --- variable source columns --------------------------------------------", 
"", "  mapping   <- character(0)", "  unmatched <- character(0)", 
"", "  for (v in spec_variables(spec)) {", "    if (v$type == \"derived\") next", 
"    m <- match_column(v$source, cols)", "    if (m$status == \"ok\") {", 
"      mapping[[v$name]] <- m$column", "    } else if (m$status == \"ambiguous\") {", 
"      # Ambiguity is always hard: picking the first match is the bug this", 
"      # repo was built to prevent.", "      hard <- c(hard, list(fail(", 
"        \"ambiguous_column\",", "        sprintf('Variable \"%s\": the text \"%s\" matches %d columns, so we cannot tell which one is meant: %s',", 
"                v$label, v$source, length(m$candidates),", "                paste(sprintf('\"%s\"', m$candidates), collapse = \", \")),", 
"        m$candidates)))", "    } else if (v$required) {", "      hard <- c(hard, list(fail(", 
"        \"missing_required\",", "        sprintf('Required variable \"%s\" needs a column matching \"%s\", which is not in the upload.',", 
"                v$label, v$source))))", "    } else {", "      unmatched <- c(unmatched, v$name)", 
"      soft <- c(soft, list(fail(", "        \"missing_optional\",", 
"        sprintf('Optional variable \"%s\" (looking for \"%s\") is not in the upload and will be left out of the report.',", 
"                v$label, v$source))))", "    }", "  }", "", 
"  # Derived variables that name explicit source columns must find them too.", 
"  for (v in spec_variables(spec, type = \"derived\")) {", "    if (is.null(v$args)) next", 
"    if (!is.null(v$args$columns)) {", "      miss <- character(0)", 
"      for (cn in v$args$columns) {", "        if (match_column(cn, cols)$status != \"ok\") miss <- c(miss, cn)", 
"      }", "      if (length(miss)) {", "        soft <- c(soft, list(fail(", 
"          \"missing_derived_input\",", "          sprintf('Derived variable \"%s\" is missing %d of its %d input columns (%s); it will be computed from the rest.',", 
"                  v$label, length(miss), length(v$args$columns),", 
"                  paste(sprintf('\"%s\"', utils::head(miss, 5)), collapse = \", \")),", 
"          miss)))", "      }", "    }", "    if (!is.null(v$args$pattern) && !is.null(v$args$n_items)) {", 
"      found <- sum(grepl(v$args$pattern, cols))", "      if (found != v$args$n_items) {", 
"        # A changed item count silently rescales the score, so this is hard.", 
"        hard <- c(hard, list(fail(", "          \"item_count_mismatch\",", 
"          sprintf('Derived variable \"%s\" expects %d items matching %s but the upload has %d. The questionnaire appears to have changed; update the spec before reporting a score.',", 
"                  v$label, v$args$n_items, v$args$pattern, found))))", 
"      }", "    }", "  }", "", "  # Anything in the export the spec never mentions: informational only.", 
"  claimed <- unname(mapping)", "  known   <- c(claimed, unlist(resolved_structural, use.names = FALSE))", 
"  for (v in spec_variables(spec, type = \"derived\")) {", "    if (!is.null(v$args$columns)) {", 
"      known <- c(known, vapply(v$args$columns, function(cn)", 
"        match_column(cn, cols)$column, character(1)))", "    }", 
"    if (!is.null(v$args$pattern)) known <- c(known, cols[grepl(v$args$pattern, cols)])", 
"  }", "  extra <- setdiff(cols, stats::na.omit(known))", "", 
"  # --- row-level structure -------------------------------------------------", 
"", "  rows <- rep(TRUE, nrow(raw))", "  n_analytic <- NA_integer_", 
"  outcome_col <- resolved_structural$outcome", "", "  if (!is.na(outcome_col)) {", 
"    y_raw <- clean_values(raw[[outcome_col]], spec$na_strings)", 
"    if (all(is.na(y_raw))) {", "      hard <- c(hard, list(fail(", 
"        \"outcome_all_missing\",", "        sprintf('The outcome column \"%s\" is present but empty for every row. No participant has a result to analyse.',", 
"                outcome_col))))", "    }", "    rows <- rows & !is.na(y_raw)", 
"  }", "", "  event_col <- resolved_structural$event", "  if (!is.na(event_col)) {", 
"    want <- spec$filter$event_value", "    ev   <- trimws(as.character(raw[[event_col]]))", 
"    keep <- !is.na(ev) & ev == want", "    if (!any(keep)) {", 
"      hard <- c(hard, list(fail(", "        \"no_matching_event\",", 
"        sprintf('No rows have \"%s\" in the \"%s\" column. Values present are: %s',", 
"                want, event_col,", "                paste(sprintf('\"%s\"', utils::head(unique(stats::na.omit(ev)), 8)),", 
"                      collapse = \", \")))))", "    }", "    rows <- rows & keep", 
"  }", "", "  for (src in spec$filter$require_nonmissing %||% character(0)) {", 
"    m <- match_column(src, cols)", "    if (m$status == \"ok\") {", 
"      rows <- rows & !is.na(clean_values(raw[[m$column]], spec$na_strings))", 
"    }", "  }", "", "  if (!any(rows)) {", "    # Only worth saying if we did not already say something more specific.", 
"    if (!length(Filter(function(f) f$code %in%", "                       c(\"no_matching_event\", \"outcome_all_missing\"), hard))) {", 
"      hard <- c(hard, list(fail(", "        \"empty_analytic_sample\",", 
"        \"No participants are left after applying the event filter and requiring an outcome result. Check that the export covers the right visit.\")))", 
"    }", "  } else {", "    n_analytic <- sum(rows)", "  }", 
"", "  # --- duplicate record IDs ------------------------------------------------", 
"", "  id_col <- resolved_structural$record_id", "  if (!is.na(id_col) && any(rows)) {", 
"    ids <- as.character(raw[[id_col]][rows])", "    dup <- unique(ids[duplicated(ids)])", 
"    if (length(dup)) {", "      hard <- c(hard, list(fail(", 
"        \"duplicate_ids\",", "        sprintf('%d participant ID%s appear%s more than once in the analysis sample: %s. Each participant must appear exactly once.',", 
"                length(dup), if (length(dup) == 1) \"\" else \"s\",", 
"                if (length(dup) == 1) \"s\" else \"\",", "                paste(utils::head(dup, 10), collapse = \", \")),", 
"        dup)))", "    }", "  }", "", "  structure(", "    list(", 
"      ok          = length(hard) == 0L,", "      hard        = hard,", 
"      soft        = soft,", "      columns     = mapping,", 
"      structural  = resolved_structural,", "      unmatched   = unmatched,", 
"      unused      = extra,", "      rows        = rows,", "      n_rows      = nrow(raw),", 
"      n_analytic  = n_analytic,", "      spec        = spec", 
"    ),", "    class = c(\"cohort_validation\", \"list\")", "  )", 
"}", "", "#' Abort with the full list of hard failures, formatted for a human reader.", 
"stop_if_invalid <- function(validation) {", "  if (validation$ok) return(invisible(validation))", 
"  msgs <- vapply(validation$hard, `[[`, character(1), \"message\")", 
"  stop(paste0(", "    \"This export cannot be analysed yet. \",", 
"    length(msgs), if (length(msgs) == 1) \" problem\" else \" problems\",", 
"    \" found:\\n\\n\",", "    paste0(\"  \", seq_along(msgs), \". \", msgs, collapse = \"\\n\\n\"),", 
"    \"\\n\"), call. = FALSE)", "}", "", "#' @export", "print.cohort_validation <- function(x, ...) {", 
"  cat(sprintf(\"<cohort_validation> %s\\n\", if (x$ok) \"PASSED\" else \"FAILED\"))", 
"  cat(sprintf(\"  rows in file:      %d\\n\", x$n_rows))", "  cat(sprintf(\"  analytic sample:   %s\\n\",", 
"              if (is.na(x$n_analytic)) \"-\" else format(x$n_analytic)))", 
"  cat(sprintf(\"  columns matched:   %d\\n\", length(x$columns)))", 
"  if (length(x$hard)) {", "    cat(\"  hard failures:\\n\")", 
"    for (f in x$hard) cat(sprintf(\"    - %s\\n\", f$message))", 
"  }", "  if (length(x$soft)) {", "    cat(sprintf(\"  soft findings:     %d\\n\", length(x$soft)))", 
"  }", "  invisible(x)", "}")

