"domains:", "  - Demographics", "  - Social history", "  - Obstetrics & gynaecology", 
"  - Medical history", "  - Clinical measurements", "  - Ultrasound", 
"  - Laboratory", "  - Mental health & QoL", "", "variables:", 
"", "  # --- Demographics --------------------------------------------------------", 
"", "  - name: age", "    source: agecalc", "    domain: Demographics", 
"    label: Age (years)", "    type: numeric", "    range: [12, 45]", 
"    required: true", "", "  - name: region", "    source: B1. Which region", 
"    domain: Demographics", "    label: Region", "    type: factor", 
"    levels: [Central, Eastern, Northern, Western, Other]", "    required: true", 
"", "  - name: residence", "    source: B2. In what type of environment", 
