"    levels: [Anglican, Catholic, Muslim, Pentecostal, Other]", 
"    recode:", "      Moslem: Muslim", "    required: true", 
"", "  - name: ses_index", "    domain: Demographics", "    label: Socioeconomic status (PCA)", 
"    type: derived", "    fn: asset_pca", "    # Explicit column list, never a regex. The original matched asset columns", 
