"    args:", "      positive: [Checked, Yes]", "      columns:", 
"        - Radio", "        - Television", "        - Bicycle", 
"        - Motor cycle", "        - Computer", "        - Tablet", 
"        - Business", "        - Bathroom", "        - Running water", 
"        - Electricity", "        - Solar", "        - Car", 
"        - Generator", "        - Mattress", "        - Bed with mattress", 
"        - Cupboard", "        - Truck", "        - Microwave", 
"        - Dining table", "        - Family home", "        - Smartphone", 
"", "  # --- Social history ------------------------------------------------------", 
"", "  - name: smoking", "    source: D1. Do you currently smoke", 
"    domain: Social history", "    label: Smoking", "    type: factor", 
"    levels: [Ever, Never]", "    recode:", "      Never smoked: Never", 
"      \"Yes, occasionally\": Ever", "      \"Yes, daily\": Ever", 
"    required: true", "", "  - name: alcohol", "    source: D9. Which of the following best describes", 
"    domain: Social history", "    label: Alcohol use", "    type: factor", 
